/* Generic read-only graph review display on the engine's original export.
 * Each annotated side is generated by the shared source-reviewed graph audit.
 * Manual review never mutates game rules or independently certifies a historical map.
 */
(async()=>{'use strict';
 const $=id=>document.getElementById(id),sha=window.WargameSyncSha256.sha256;
 const NS='http://www.w3.org/2000/svg';
 let selected=null,edges=[],audit=null,map=null,reviews={};const nodes=new Map();
 const clone=x=>JSON.parse(JSON.stringify(x));
 const pair=e=>e.id;
 const source=x=>{const {integrity,...payload}=x;return sha(JSON.stringify(payload))===integrity?.digest&&integrity?.algorithm==='SHA-256'};
 function kind(e){return e.majorRiver?'major-river':e.river?'river':e.rail?'rail':'plain'}
 function status(id){return reviews[id]?.status||'unreviewed'}
 function msg(t){$('message').textContent=t||''}
 function render(){
  const confirmed=Object.values(reviews).filter(x=>x.status==='confirmed').length,disputed=Object.values(reviews).filter(x=>x.status==='disputed').length;
  $('counts').textContent=`${map.cells.length} source hexes · ${edges.length} physical sides · `+
   `${audit.coverage.rails} rail · ${audit.coverage.river} river · ${audit.coverage.majorRiver} major river · `+
   `${confirmed} reviewed · ${disputed} disputed · ${edges.length-confirmed-disputed} unreviewed`;
  const f=$('filter').value;
  for(const e of edges){const node=nodes.get(e.id),k=kind(e),s=status(e.id);
   // A rail can share a side with an ordinary/Major River. Filter by each
   // independent feature, not only by the color's visual priority.
   const included=f==='all'||(f==='rail'&&e.rail)||(f==='river'&&e.river)||
    (f==='major-river'&&e.majorRiver)||(f==='plain'&&!e.rail&&!e.river&&!e.majorRiver)||
    (f==='unreviewed'&&s==='unreviewed')||(f==='disputed'&&s==='disputed');
   if(!included)node.setAttribute('hidden','');
   else node.removeAttribute('hidden');
   node.dataset.review=s;node.dataset.selected=String(e.id===selected);
   node.querySelector('title').textContent=`${e.a} / ${e.b} — ${k} — ${s}`;
   node.querySelector('.hit').setAttribute('aria-label',`Edge ${e.a} to ${e.b}, ${k}, ${s}`);
  }
  if(selected){const e=edges.find(x=>pair(x)===selected);
   $('selection').textContent=`${e.a} ↔ ${e.b} · ${kind(e)}${e.rail?' · railway':''}`+
     ` · Review: ${status(selected)}. Experimental source graph; manual review is not historical certification.`;
   $('note').value=reviews[selected]?.note||'';
  }else{$('selection').textContent='Select a source candidate edge.';$('note').value='';}
 }
 function select(id){selected=id;render();msg('')}
 function update(statusValue, note){
  if(!selected)throw Error('Select an edge first');
  if(!['confirmed','disputed','unreviewed'].includes(statusValue))throw Error('Invalid review classification');
  if(typeof note!=='string'||note.length>500||/[\x00-\x08\x0b-\x1f\x7f]/.test(note))throw Error('Invalid review note');
  if(statusValue==='unreviewed'){delete reviews[selected]}
  else reviews[selected]={status:statusValue,...(note.trim()?{note:note.trim()}:{})};
  render();msg('Manual source review updated; this does not alter game authorization.');
 }
 function draft(){const body={format:'movement-edge-review-draft',version:1,
   sourceAuditSHA256:audit.integrity.digest,mapId:map.id,
   reviews:Object.fromEntries(Object.entries(reviews).sort(([a],[b])=>a.localeCompare(b))),
   gameplayAuthorized:false,status:'UNAPPROVED-SOURCE-CANDIDATE-DRAFT'};
  return {...body,integrity:{algorithm:'SHA-256',digest:sha(JSON.stringify(body))}}
 }
 function restore(x){
  const keys=['format','version','sourceAuditSHA256','mapId','reviews','gameplayAuthorized','status','integrity'];
  if(!x||Object.keys(x).sort().join('|')!==keys.sort().join('|')||!source(x)||
   x.format!=='movement-edge-review-draft'||x.version!==1||x.sourceAuditSHA256!==audit.integrity.digest||
   x.mapId!==map.id||x.gameplayAuthorized!==false||x.status!=='UNAPPROVED-SOURCE-CANDIDATE-DRAFT'||
   !x.reviews||typeof x.reviews!=='object'||Array.isArray(x.reviews))throw Error('Invalid or source-mismatched edge review draft');
  const next={};for(const [id,v] of Object.entries(x.reviews)){
   if(!nodes.has(id)||!v||typeof v!=='object'||Array.isArray(v)||
    !['confirmed','disputed'].includes(v.status)||
    Object.keys(v).some(k=>!['status','note'].includes(k))||
    (v.note!==undefined&&(typeof v.note!=='string'||v.note.length<1||v.note.length>500||v.note!==v.note.trim()||/[\x00-\x08\x0b-\x1f\x7f]/.test(v.note))))
    throw Error('Invalid reviewed hexside in draft');
   next[id]=clone(v);
  }
  reviews=next;selected=null;render();msg('Source-matched manual review restored; this draft does not change game authorization.');
 }
 function bind(id,fn){$(id).addEventListener('click',()=>{try{fn()}catch(e){msg(e.message)}})}
 try{
  const fetchJ=async p=>{const r=await fetch(p);if(!r.ok)throw Error('Source file unavailable: '+p);return r.json()};
  const cfg=await fetchJ('kiev.json');if(cfg.candidateOnly!==true||cfg.scenarioId!=='kiev')throw Error('Only pinned diagnostic source supported');
  [map,audit]=await Promise.all([fetchJ(cfg.map),fetchJ(cfg.candidateEdges)]);
  if(!source(audit)||cfg.expectedAuditDigest!==audit.integrity.digest||
   cfg.expectedSourceSvgSHA256!==audit.source.sourceSvgSHA256||audit.scope!=='READ-ONLY-SOURCE-REVIEW-NOT-HISTORICAL-CERTIFICATION'||audit.gameplayAuthorized!==false||
   audit.source.mapId!==map.id||audit.source.mapImageSHA256!==map.sourceImageSHA256||
   audit.source.sourceSvgSHA256!==map.definitiveTerrainAudit?.sourceSvgSha256||
   audit.source.currentGraphAuthorization!=='source-verified-experimental-not-historically-certified'||
   audit.coverage.cells!==map.cells.length||audit.coverage.edges!==audit.edges.length||
   audit.edges.length!==442)throw Error('Source-reviewed candidate audit mismatch');
  const centers=new Map(map.cells.map(c=>[c.id,c.pixelCenter]));
  if(centers.size!==map.cells.length)throw Error('Duplicate map cells');
  const keys=new Set();let rails=0,rivers=0,majors=0;
  for(const e of audit.edges){
   if(!centers.has(e.a)||!centers.has(e.b)||e.id!==[e.a,e.b].sort().join(':')||keys.has(e.id)||
    !Array.isArray(e.side)||e.side.length!==2||e.side.some(p=>!Array.isArray(p)||p.length!==2||p.some(x=>!Number.isFinite(x)))||
    e.river&&e.majorRiver)throw Error('Invalid candidate source edge inventory');
   keys.add(e.id);rails+=Number(e.rail);rivers+=Number(e.river);majors+=Number(e.majorRiver);
  }
  if(rails!==audit.coverage.rails||rivers!==audit.coverage.river||majors!==audit.coverage.majorRiver)throw Error('Candidate edge feature count mismatch');
  edges=audit.edges;
  for(const e of edges){
   const group=document.createElementNS(NS,'g'),line=document.createElementNS(NS,'line'),hit=document.createElementNS(NS,'line');
   for(const el of [line,hit]){el.setAttribute('x1',e.side[0][0]);el.setAttribute('y1',e.side[0][1]);el.setAttribute('x2',e.side[1][0]);el.setAttribute('y2',e.side[1][1]);}
   line.classList.add('visible');hit.classList.add('hit');hit.setAttribute('tabindex','0');hit.setAttribute('role','button');
   hit.addEventListener('click',()=>select(e.id));hit.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();select(e.id)}});
   const title=document.createElementNS(NS,'title');group.dataset.edge=e.id;group.dataset.kind=kind(e);group.append(line,hit,title);$('edges').appendChild(group);nodes.set(e.id,group);
  }
  $('source').textContent=JSON.stringify({source:audit.source,coverage:audit.coverage,candidateDigest:audit.integrity.digest},null,2);
  $('filter').addEventListener('change',render);
  bind('next',()=>{const pending=edges.filter(x=>status(x.id)==='unreviewed').sort((a,b)=>
   (a.majorRiver?0:a.river?1:a.rail?2:3)-(b.majorRiver?0:b.river?1:b.rail?2:3)||a.id.localeCompare(b.id));
   if(!pending.length){msg('No unreviewed sides remain. This remains a manual draft.');return;}
   $('filter').value='all';select(pending[0].id);nodes.get(selected).querySelector('.hit').focus();
   nodes.get(selected).scrollIntoView({block:'nearest',inline:'nearest'});
  });
  bind('confirm',()=>update('confirmed',$('note').value));bind('dispute',()=>update('disputed',$('note').value));bind('clear',()=>update('unreviewed',''));
  bind('save-note',()=>{if(!selected)throw Error('Select an edge first');if(status(selected)==='unreviewed')throw Error('Classify the edge before attaching a note');update(status(selected),$('note').value)});
  bind('reset',()=>{reviews={};selected=null;render();msg('Manual draft reset; source candidate unchanged.')});
  bind('save',()=>{const content=JSON.stringify(draft(),null,2)+'\n';const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='kiev-movement-edges-UNAPPROVED-DRAFT.json';a.click();URL.revokeObjectURL(url);msg('Exported review draft only; gameplay authorization unchanged.')});
  $('load').addEventListener('change',async event=>{try{if(event.target.files?.[0])restore(JSON.parse(await event.target.files[0].text()))}catch(e){msg('Import rejected: '+e.message)}finally{event.target.value=''}});
  render();window.MovementEdgeReview=Object.freeze({snapshot:()=>clone({selected,reviews,source:audit.integrity.digest}),exportDraft:()=>draft(),audit:()=>clone({source:audit.source,coverage:audit.coverage})});
 }catch(e){$('counts').textContent='Source graph audit unavailable';msg(e.message)}
})();
